mapper.select:
        select
        messageInfo.*,
        student.stu_name,
        student.stu_img,
        teachers.tea_name,
        teachers.tea_img
        from message_info messageInfo
        left join student student on messageInfo.send_user_id = student.id
		left join teachers teachers on messageInfo.accept_user_id = teachers.id

            and messageInfo.id = #{id}
            and messageInfo.info = #{info}
            and messageInfo.message_id = #{messageId}
            and messageInfo.position = #{position}
            and messageInfo.send_user_id = #{sendUserId}
            and messageInfo.accept_user_id = #{acceptUserId}
            and messageInfo.create_time = #{createTime}
            and student.stu_name like concat('%',#{stuName},'%')
            and student.stu_img = #{stuImg}
            and teachers.tea_name like concat('%',#{teaName},'%')
            and teachers.tea_img = #{teaImg}

        order by id asc

            limit #{current},#{pageSize}

        select count(*) from message_info messageInfo
        left join student student on messageInfo.send_user_id = student.id
		left join teachers teachers on messageInfo.accept_user_id = teachers.id

            and messageInfo.id = #{id}
            and messageInfo.info = #{info}
            and messageInfo.message_id = #{messageId}
            and messageInfo.position = #{position}
            and messageInfo.send_user_id = #{sendUserId}
            and messageInfo.accept_user_id = #{acceptUserId}
            and messageInfo.create_time = #{createTime}
            and student.stu_name like concat('%',#{stuName},'%')
            and student.stu_img = #{stuImg}
            and teachers.tea_name like concat('%',#{teaName},'%')
            and teachers.tea_img = #{teaImg}
